mapper.select:
SELECT m.id, m.user_id AS userId, m.stall_id AS stallId, m.name, m.description, m.logo_url AS logoUrl, m.business_hours AS businessHours, m.status, c.name AS canteenName, c.type AS canteenType, s.name AS stallName, m.average_score AS averageScore, ( SELECT COUNT(1) FROM dish d WHERE d.merchant_id = m.id AND d.status IN ('ON_SALE', 'SOLD_OUT') ) AS dishCount FROM merchant m INNER JOIN stall s ON s.id = m.stall_id AND s.status = 'OPEN' INNER JOIN canteen c ON c.id = s.canteen_id AND c.status = 'OPEN' WHERE m.apply_status = 'APPROVED' AND m.status = #{status}
AND c.id = #{canteenId}
AND s.id = #{stallId}
ORDER BY m.id ASC

SELECT
    (
        SELECT COUNT(1)
        FROM review r
        INNER JOIN dish d ON d.id = r.dish_id
        WHERE d.merchant_id = #{merchantId}
          AND r.status = 'VISIBLE'
          AND r.created_at >= #{startTime}
          AND r.created_at < #{endTime}
    ) AS todayReviewCount,
    (
        SELECT COALESCE(ROUND(AVG(r.overall_score), 2), 0)
        FROM review r
        INNER JOIN dish d ON d.id = r.dish_id
        WHERE d.merchant_id = #{merchantId}
          AND r.status = 'VISIBLE'
          AND r.created_at >= #{startTime}
          AND r.created_at < #{endTime}
    ) AS todayAverageScore,
    (
        SELECT COALESCE(ROUND(AVG(r.taste_score), 2), 0)
        FROM review r
        INNER JOIN dish d ON d.id = r.dish_id
        WHERE d.merchant_id = #{merchantId}
          AND r.status = 'VISIBLE'
          AND r.created_at >= #{startTime}
          AND r.created_at < #{endTime}
    ) AS todayTasteScore,
    (
        SELECT COALESCE(ROUND(AVG(r.portion_score), 2), 0)
        FROM review r
        INNER JOIN dish d ON d.id = r.dish_id
        WHERE d.merchant_id = #{merchantId}
          AND r.status = 'VISIBLE'
          AND r.created_at >= #{startTime}
          AND r.created_at < #{endTime}
    ) AS todayPortionScore,
    (
        SELECT COALESCE(ROUND(AVG(r.value_score), 2), 0)
        FROM review r
        INNER JOIN dish d ON d.id = r.dish_id
        WHERE d.merchant_id = #{merchantId}
          AND r.status = 'VISIBLE'
          AND r.created_at >= #{startTime}
          AND r.created_at < #{endTime}
    ) AS todayValueScore,
    (
        SELECT COUNT(1)
        FROM feedback f
        WHERE f.merchant_id = #{merchantId}
          AND f.created_at >= #{startTime}
          AND f.created_at < #{endTime}
    ) AS todayFeedbackCount,
    (
        SELECT COUNT(1)
        FROM feedback f
        WHERE f.merchant_id = #{merchantId}
          AND f.status = 'PENDING'
          AND f.created_at >= #{startTime}
          AND f.created_at < #{endTime}
    ) AS todayNewPendingFeedbackCount,
    (
        SELECT COUNT(1)
        FROM feedback f
        WHERE f.merchant_id = #{merchantId}
          AND f.status = 'PENDING'
    ) AS totalPendingFeedbackCount,
    (
        SELECT COUNT(1)
        FROM favorite fav
        INNER JOIN dish d ON d.id = fav.target_id
        WHERE d.merchant_id = #{merchantId}
          AND fav.target_type = 'DISH'
          AND fav.created_at >= #{startTime}
          AND fav.created_at < #{endTime}
    ) AS todayFavoriteCount,
    (
        SELECT COUNT(1)
        FROM eat_list el
        INNER JOIN dish d ON d.id = el.dish_id
        WHERE d.merchant_id = #{merchantId}
          AND el.created_at >= #{startTime}
          AND el.created_at < #{endTime}
    ) AS todayWantEatCount,
    (
        SELECT COUNT(1)
        FROM eat_list el
        INNER JOIN dish d ON d.id = el.dish_id
        WHERE d.merchant_id = #{merchantId}
          AND el.eaten_at >= #{startTime}
          AND el.eaten_at < #{endTime}
    ) AS todayEatenCount,
    (
        SELECT COUNT(1)
        FROM lottery_record lr
        INNER JOIN dish d ON d.id = lr.source_id
        WHERE d.merchant_id = #{merchantId}
          AND lr.source_type = 'DISH'
          AND lr.created_at >= #{startTime}
          AND lr.created_at < #{endTime}
    ) AS todayLotteryCount,
    (
        SELECT COUNT(1)
        FROM lottery_record lr
        INNER JOIN dish d ON d.id = lr.source_id
        WHERE d.merchant_id = #{merchantId}
          AND lr.source_type = 'DISH'
          AND lr.result_action IN ('ACCEPT', 'FAVORITE')
          AND lr.created_at >= #{startTime}
          AND lr.created_at < #{endTime}
    ) AS todayAcceptedLotteryCount,
    (
        SELECT COUNT(1)
        FROM merchant_recommendation mr
        WHERE mr.merchant_id = #{merchantId}
          AND mr.status = 'ACTIVE'
          AND mr.start_time < NOW()
          AND mr.end_time >= NOW()
    ) AS activeRecommendationCount,
    (
        SELECT COALESCE(SUM(mr.click_count), 0)
        FROM merchant_recommendation mr
        WHERE mr.merchant_id = #{merchantId}
          AND mr.status = 'ACTIVE'
          AND mr.start_time < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
          AND mr.end_time >= CURDATE()
    ) AS todayRecommendClickCount

SELECT
    d.id AS dishId,
    d.name AS dishName,
    d.status,
    d.price,
    d.average_score AS averageScore,
    d.view_count AS viewCount,
    d.favorite_count AS favoriteCount,
    d.review_count AS reviewCount,
    (
        SELECT COUNT(1)
        FROM review r
        WHERE r.dish_id = d.id
          AND r.status = 'VISIBLE'
          AND r.created_at >= #{startTime}
          AND r.created_at < #{endTime}
    ) AS todayReviewCount,
    (
        SELECT COUNT(1)
        FROM feedback f
        WHERE f.dish_id = d.id
          AND f.created_at >= #{startTime}
          AND f.created_at < #{endTime}
    ) AS todayFeedbackCount,
    (
        SELECT COUNT(1)
        FROM favorite fav
        WHERE fav.target_id = d.id
          AND fav.target_type = 'DISH'
          AND fav.created_at >= #{startTime}
          AND fav.created_at < #{endTime}
    ) AS todayFavoriteCount,
    (
        SELECT COUNT(1)
        FROM eat_list el
        WHERE el.dish_id = d.id
          AND el.created_at >= #{startTime}
          AND el.created_at < #{endTime}
    ) AS todayWantEatCount,
    (
        SELECT COUNT(1)
        FROM lottery_record lr
        WHERE lr.source_id = d.id
          AND lr.source_type = 'DISH'
          AND lr.created_at >= #{startTime}
          AND lr.created_at < #{endTime}
    ) AS todayLotteryCount
FROM dish d
WHERE d.merchant_id = #{merchantId}
ORDER BY (todayFavoriteCount * 3 + todayReviewCount * 2 + todayFeedbackCount + todayWantEatCount + todayLotteryCount) DESC,
         (d.view_count + d.favorite_count * 3 + d.review_count * 2) DESC,
         d.id DESC
LIMIT #{limit}
